/** Go: func StringToMsgIDs(str string, logLevel LogLevel, overrides map[MsgID]LogLevel) */
export function StringToMsgIDs(str: string, logLevel: LogLevel, overrides: Map<MsgID, LogLevel>): void {
  for (const [name, id] of msgIDStringToID) {
    if (name === str) {
      overrides.set(id, logLevel);
      return;
    }
  }
  for (const [name, first, last] of msgIDRanges) {
    if (name === str) {
      for (let i = first; i <= last; i++) overrides.set(i, logLevel);
      return;
    }
  }
  // 无效条目一律忽略：消息 ID 可能在代码写完之后被改名/删除
}

/** Go: func StringToMaximumMsgID(id string) MsgID */
export function StringToMaximumMsgID(id: string): MsgID {
  const overrides = new Map<MsgID, LogLevel>();
  let maxID: MsgID = MsgID_None;
  StringToMsgIDs(id, LogLevel.Info, overrides);
  for (const k of overrides.keys()) if (k > maxID) maxID = k;
  return maxID;
}
